  --dss-component-padding-sm: 12px;
  --dss-component-padding-md: 16px; /* Padrão */
  --dss-component-padding-lg: 20px;
  --dss-component-padding-xl: 24px;
  /* Margens entre componentes */
  --dss-component-margin-xs: 8px;
  --dss-component-margin-sm: 12px;
  --dss-component-margin-md: 16px; /* Padrão */
  --dss-component-margin-lg: 24px;
  --dss-component-margin-xl: 32px;
  /* ===========================================
     8. BREAKPOINTS PARA ACESSIBILIDADE
     Suporte para zoom e reflow de conteúdo
     ✅ WCAG 2.1 AA (SC 1.4.10): Reflow
     =========================================== */
  --dss-breakpoint-xs: 320px; /* Mobile pequeno, zoom 300% */
  --dss-breakpoint-sm: 640px; /* Mobile, zoom 200% */
  --dss-breakpoint-md: 768px; /* Tablet */
  --dss-breakpoint-lg: 1024px; /* Desktop pequeno */
  --dss-breakpoint-xl: 1280px; /* Desktop padrão */
  --dss-breakpoint-2xl: 1536px; /* Desktop grande */
