  --dss-opacity-backdrop: var(--dss-opacity-75);
  /* Opacidades para overlays de marca */
  --dss-opacity-brand-subtle: var(--dss-opacity-8);
  --dss-opacity-brand-light: var(--dss-opacity-12);
  --dss-opacity-brand-medium: var(--dss-opacity-16);
  --dss-opacity-brand-strong: var(--dss-opacity-24);
