/* ==========================================================================
   DSS - TOKENS DE Z-INDEX
   Sistema de camadas para controle de profundidade
   ========================================================================== */
:root {
  /* ===========================================
     1. CAMADAS BASE
     =========================================== */
  --dss-z-index-auto: auto;
  --dss-z-index-0: 0;
  --dss-z-index-10: 10;
  --dss-z-index-20: 20;
  --dss-z-index-30: 30;
  --dss-z-index-40: 40;
  --dss-z-index-50: 50;
