/* ==========================================================================
   DSS - TOKENS DE MARCA HUB
   Sobrescritas para contexto Sansys Hub (Laranja/Marrom)
   ========================================================================== */
[data-brand=hub] {
  /* ===========================================
     1. TOKENS DE AÇÃO (ACTION TOKENS)
     Primary actions usam cores da marca Hub
     =========================================== */
  --dss-action-primary: var(--dss-hub-600); /* #ef7a11 */
  --dss-action-primary-light: var(--dss-hub-300); /* #fbcb76 */
  --dss-action-primary-disable: var(--dss-hub-200); /* #fde2ab */
  --dss-action-primary-hover: var(--dss-hub-800); /* #984614 */
  --dss-action-primary-deep: var(--dss-hub-900); /* #7a3614 */
  --dss-action-primary-bg: var(--dss-hub-50); /* #fff9ed */
  --dss-action-primary-text: white;
  /* Secondary e tertiary mantêm cores semânticas */
  --dss-action-secondary: var(--dss-secondary); /* Mantém verde semântico */
  --dss-action-tertiary: var(--dss-tertiary); /* Mantém laranja semântico */
  --dss-action-accent: var(--dss-accent); /* Mantém roxo semântico */
  /* ===========================================
     2. TOKENS DE MARCA ESPECÍFICOS
     =========================================== */
  --dss-brand-primary: var(--dss-hub-600);
  --dss-brand-secondary: var(--dss-hub-300);
  --dss-brand-tertiary: var(--dss-hub-800);
  --dss-brand-accent: var(--dss-hub-400);
  --dss-brand-light: var(--dss-hub-100);
  --dss-brand-lighter: var(--dss-hub-50);
  --dss-brand-dark: var(--dss-hub-900);
  --dss-brand-darker: var(--dss-hub-950);
  --dss-brand-hover: var(--dss-hub-700); /* Estado hover sobre primary — #bf590f */
  --dss-brand-disable: var(--dss-hub-200); /* Estado desabilitado — #fde2ab */
  --dss-brand-deep: var(--dss-hub-800); /* Estado active/pressionado — #984614 */
  --dss-brand-background: var(--dss-hub-50);
  --dss-brand-surface: var(--dss-hub-100);
  --dss-brand-border: var(--dss-hub-200);
  --dss-brand-text: var(--dss-hub-900);
  /* ===========================================
     3. TOKENS DE SUPERFÍCIE BRANDÁVEIS
     =========================================== */
  --dss-surface-brand-subtle: rgba(239, 122, 17, 0.08); /* Hub-600 8% */
  --dss-surface-brand-light: rgba(239, 122, 17, 0.12); /* Hub-600 12% */
  --dss-surface-brand-medium: rgba(239, 122, 17, 0.16); /* Hub-600 16% */
  --dss-surface-brand-strong: rgba(239, 122, 17, 0.24); /* Hub-600 24% */
  --dss-surface-brand-primary: var(--dss-hub-50);
  --dss-surface-brand-secondary: var(--dss-hub-100);
  /* ===========================================
     4. TOKENS DE TEXTO BRANDÁVEIS
     =========================================== */
  --dss-text-brand-primary: var(--dss-hub-800);
  --dss-text-brand-secondary: var(--dss-hub-600);
  --dss-text-brand-tertiary: var(--dss-hub-500);
  --dss-text-brand-accent: var(--dss-hub-300);
  --dss-text-brand-on-dark: white;
  --dss-text-brand-on-light: var(--dss-hub-900);
  /* ===========================================
     5. TOKENS DE BORDA BRANDÁVEIS
     =========================================== */
  --dss-border-brand-primary: var(--dss-hub-300);
  --dss-border-brand-secondary: var(--dss-hub-200);
  --dss-border-brand-accent: var(--dss-hub-600);
  --dss-border-brand-focus: var(--dss-hub-600);
  --dss-border-brand-error: var(--dss-negative); /* Mantém vermelho semântico */
  /* ===========================================
     6. TOKENS DE SOMBRA BRANDÁVEIS
     =========================================== */
  --dss-shadow-brand-sm: 0 1px 3px rgba(239, 122, 17, 0.15);
  --dss-shadow-brand-md: 0 4px 6px rgba(239, 122, 17, 0.15);
  --dss-shadow-brand-lg: 0 10px 15px rgba(239, 122, 17, 0.15);
  --dss-shadow-brand-xl: 0 20px 25px rgba(239, 122, 17, 0.15);
  --dss-elevation-brand-1: 0 1px 3px rgba(239, 122, 17, 0.15);
  --dss-elevation-brand-2: 0 4px 6px rgba(239, 122, 17, 0.15);
  /* ===========================================
     7. TOKENS DE FOCO BRANDÁVEIS
     =========================================== */
  --dss-focus-ring-brand: 0 0 0 3px rgba(239, 122, 17, 0.5);
  --dss-focus-ring-brand-inset: inset 0 0 0 3px rgba(239, 122, 17, 0.5);
  --dss-outline-focus-brand: 2px solid var(--dss-hub-600);
  /* ===========================================
     8. GRADIENTES BRANDÁVEIS
     =========================================== */
  --dss-gradient-brand-vertical: linear-gradient(180deg, var(--dss-hub-400) 0%, var(--dss-hub-600) 100%);
  --dss-gradient-brand-horizontal: linear-gradient(90deg, var(--dss-hub-400) 0%, var(--dss-hub-600) 100%);
  --dss-gradient-brand-diagonal: linear-gradient(135deg, var(--dss-hub-400) 0%, var(--dss-hub-600) 100%);
  --dss-gradient-brand-radial: radial-gradient(circle, var(--dss-hub-400) 0%, var(--dss-hub-600) 100%);
  --dss-gradient-brand-light: linear-gradient(135deg, var(--dss-hub-50) 0%, var(--dss-hub-100) 100%);
  --dss-gradient-brand-dark: linear-gradient(135deg, var(--dss-hub-600) 0%, var(--dss-hub-800) 100%);
  /* ===========================================
     9. ❌ REMOVIDO: TOKENS DE COMPONENTES BRANDÁVEIS
     =========================================== */
  /* ANTI-PADRÃO CORRIGIDO - Sprint 1
   *
   * Tokens removidos (14 tokens --dss-component-*):
   * - --dss-component-btn-primary-bg
   * - --dss-component-btn-primary-hover
   * - --dss-component-btn-primary-active
   * - --dss-component-btn-primary-text
   * - --dss-component-card-bg
   * - --dss-component-card-border
   * - --dss-component-card-header-bg
   * - --dss-component-header-bg
   * - --dss-component-header-text
   * - --dss-component-header-border
   * - --dss-component-footer-bg
   * - --dss-component-footer-text
   * - --dss-component-sidebar-bg
   * - --dss-component-sidebar-border
   *
   * CORREÇÃO: Componentes devem consumir tokens genéricos:
   * .dss-button { background: var(--dss-action-primary); }
   * .dss-card { background: var(--dss-surface-default); }
   */
  /* ===========================================
     10. TOKENS PARA QUASAR (INTEGRAÇÃO)
     =========================================== */
  --quasar-primary: var(--dss-hub-600);
  --quasar-primary-hover: var(--dss-hub-700);
  --quasar-primary-active: var(--dss-hub-800);
  --quasar-primary-disable: var(--dss-hub-200);
  /* ===========================================
     11. ACESSIBILIDADE - CONTRASTE ESPECÍFICO
     =========================================== */
  /* Nota: Hub-600 (#ef7a11) tem contraste 3.8:1 com branco (apenas para UI grande)
      Portanto, NÃO usar para texto normal. Apenas para UI elements grandes. */
  --dss-contrast-brand-primary-on-white: 3.8; /* ⚠️ Apenas UI grande */
  --dss-contrast-brand-primary-on-dark: 10.2; /* ✅ Excelente sobre fundo escuro */
  /* Combinações aprovadas para Hub */
  --dss-contrast-safe-brand-text: var(--dss-hub-900); /* #7a3614 sobre branco = 11.6:1 ✅ */
  --dss-contrast-safe-brand-bg: var(--dss-hub-600); /* Para backgrounds apenas */
  --dss-contrast-safe-brand-ui: var(--dss-hub-700); /* #bf590f sobre branco = 5.2:1 ✅ (UI grande) */
  /* ===========================================
     12. CLASSES DE UTILIDADE ESPECÍFICAS
     =========================================== */
}
[data-brand=hub] .dss-brand-hub-only {
  /* Classes que só aparecem no contexto Hub */
}

