/* 6. Dark Mode Theme */
/* ==========================================================================
   DSS - DARK THEME - COLORS
   Cores otimizadas para funcionarem tanto em light quanto dark mode
   ========================================================================== */
/**
 * ESTRATÉGIA DARK MODE:
 *
 * 1. Cores de ação (primary, secondary, tertiary, accent) e feedback
 *    (positive, negative, warning, info) NÃO mudam - foram escolhidas
 *    para funcionar bem em ambos os modos
 *
 * 2. Cores de brand (hub, water, waste) NÃO mudam quando usadas em
 *    componentes com background (filled, unelevated)
 *
 * 3. EXCEÇÕES que precisam de versões mais claras:
 *    - Waste em contextos "vazados" (flat, outline) ou texto direto
 *    - Dark em contextos "vazados" (flat, outline) ou texto direto
 *    - Variações -deep de qualquer cor
 */
[data-theme=dark] {
  /* ===========================================
     BACKGROUNDS / SURFACES
     Inverter de claro (gray-50) para escuro (gray-800)
     =========================================== */
  --dss-surface-default: var(--dss-gray-800); /* #262626 - Fundo principal */
  --dss-surface-subtle: var(--dss-gray-700); /* #525252 - Elevação suave */
  --dss-surface-muted: var(--dss-gray-600); /* #737373 - Áreas rebaixadas */
  --dss-surface-disabled: var(--dss-gray-700); /* #525252 - Desabilitado */
  /* Overlays invertidos */
  --dss-surface-overlay: rgba(255, 255, 255, 0.05);
  --dss-surface-hover: rgba(255, 255, 255, 0.08);
  --dss-surface-active: rgba(255, 255, 255, 0.12);
  --dss-surface-selected: rgba(31, 134, 222, 0.24);
  /* ===========================================
     TEXT COLORS
     Inverter de escuro (dark) para claro (gray-200)
     =========================================== */
  --dss-text-body: var(--dss-gray-200); /* #f5f5f5 - Texto principal */
  --dss-text-subtle: var(--dss-gray-400); /* #d4d4d4 - Texto secundário */
  --dss-text-muted: var(--dss-gray-500); /* #a3a3a3 - Texto terciário */
  --dss-text-inverse: var(--dss-gray-900); /* #0a0a0a - Texto escuro */
  --dss-text-disabled: var(--dss-gray-600); /* #737373 - Desabilitado */
  /* ===========================================
     BORDERS
     Inverter de claro (gray-300) para médio (gray-600)
     =========================================== */
  --dss-border-default: var(--dss-gray-600); /* #737373 */
  --dss-border-subtle: var(--dss-gray-700); /* #525252 */
  --dss-border-strong: var(--dss-gray-500); /* #a3a3a3 */
  --dss-border-disabled: var(--dss-gray-700); /* #525252 */
  /* ===========================================
     ACTIONS - MANTÉM CORES ORIGINAIS
     Cores escolhidas para funcionar bem em light e dark
     =========================================== */
  /* Primary (Azul) - NÃO MUDA */
  /* --dss-action-primary: mantém valor original */
  /* --dss-action-primary-hover: mantém valor original */
  /* --dss-action-primary-deep: mantém valor original */
  --dss-action-primary-disable: var(--dss-gray-600);
  /* Secondary (Verde/Turquesa) - NÃO MUDA */
  /* --dss-action-secondary: mantém valor original */
  /* --dss-action-secondary-hover: mantém valor original */
  /* --dss-action-secondary-deep: mantém valor original */
  --dss-action-secondary-disable: var(--dss-gray-600);
  /* Tertiary (Laranja) - NÃO MUDA */
  /* --dss-action-tertiary: mantém valor original */
  /* --dss-action-tertiary-hover: mantém valor original */
  /* --dss-action-tertiary-deep: mantém valor original */
  --dss-action-tertiary-disable: var(--dss-gray-600);
  /* Accent (Roxo) - NÃO MUDA */
  /* --dss-action-accent: mantém valor original */
  /* --dss-action-accent-hover: mantém valor original */
  /* --dss-action-accent-deep: mantém valor original */
  --dss-action-accent-disable: var(--dss-gray-600);
  /* Dark - USA VERSÃO LIGHT em contextos sem background */
  /* Nota: Em botões filled/unelevated mantém, em flat/outline usa -light */
  /* Implementado via classes específicas dos componentes */
  /* ===========================================
     FEEDBACK - MANTÉM CORES ORIGINAIS
     Cores escolhidas para funcionar bem em light e dark
     =========================================== */
  /* Success (Verde) - NÃO MUDA */
  /* --dss-feedback-success: mantém valor original */
  /* --dss-feedback-success-hover: mantém valor original */
  /* Error (Vermelho) - NÃO MUDA */
  /* --dss-feedback-error: mantém valor original */
  /* --dss-feedback-error-hover: mantém valor original */
  /* Warning (Amarelo) - NÃO MUDA */
  /* --dss-feedback-warning: mantém valor original */
  /* --dss-feedback-warning-hover: mantém valor original */
  /* Info (Azul Claro) - NÃO MUDA */
  /* --dss-feedback-info: mantém valor original */
  /* --dss-feedback-info-hover: mantém valor original */
  /* ===========================================
     SHADOWS (mais sutis em dark mode)
     =========================================== */
  --dss-shadow-sm: 0 1px 3px rgba(0, 0, 0, 0.5);
  --dss-shadow-md: 0 4px 6px rgba(0, 0, 0, 0.6);
  --dss-shadow-lg: 0 10px 15px rgba(0, 0, 0, 0.7);
  --dss-shadow-xl: 0 20px 25px rgba(0, 0, 0, 0.8);
  --dss-shadow-2xl: 0 25px 50px rgba(0, 0, 0, 0.9);
  /* ===========================================
     ⚠️ TOKENS COMPONENT-SPECIFIC REMOVIDOS (JAN 2025 - SPRINT 3)
     =========================================== */
  /*
   * REFATORAÇÃO: Dark mode agora usa tokens genéricos automaticamente
   *
   * ❌ REMOVIDOS (3 sobrescritas de dark mode):
   * --dss-elevation-card           → Usa: var(--dss-elevation-1) automaticamente
   * --dss-elevation-card-hover     → Usa: var(--dss-elevation-2) automaticamente
   * --dss-elevation-modal          → Usa: var(--dss-elevation-4) automaticamente
   *
   * Os tokens genéricos herdam as sombras base do dark mode:
   * --dss-elevation-1 = var(--dss-shadow-sm) = rgba(0,0,0,0.5) em dark
   * --dss-elevation-2 = var(--dss-shadow-md) = rgba(0,0,0,0.6) em dark
   * --dss-elevation-4 = var(--dss-shadow-xl) = rgba(0,0,0,0.8) em dark
   */
  /* ===========================================
     INPUT/FORM COLORS
     =========================================== */
  --dss-input-background: var(--dss-gray-700); /* #525252 */
  --dss-input-border: var(--dss-gray-600); /* #737373 */
  --dss-input-border-hover: var(--dss-gray-500); /* #a3a3a3 */
  --dss-input-border-focus: var(--dss-action-primary); /* Mantém primary original */
  --dss-input-text: var(--dss-gray-200); /* #f5f5f5 */
  --dss-input-placeholder: var(--dss-gray-500); /* #a3a3a3 */
}

/* ===========================================
   EXCEÇÃO: WASTE em contextos "vazados"
   Usar waste-500 (mais claro) para flat/outline/texto
   =========================================== */
[data-theme=dark][data-brand=waste] {
  /* Texto direto com cor Waste precisa ser mais claro */
  --dss-text-brand-primary: var(--dss-waste-500); /* #18b173 (mais claro que -600) */
  /* Para componentes sem background mantém a cor original */
  /* Isso será aplicado via classes específicas .dss-button--flat, .dss-button--outlined */
}

