.q-app .dss-skip-to-content:focus {
  position: fixed;
  top: var(--dss-spacing-2);
  left: var(--dss-spacing-2);
  z-index: var(--dss-z-index-maximum);
  padding: var(--dss-spacing-3) var(--dss-spacing-4);
