  box-shadow: var(--dss-shadow-lg);
  text-decoration: none;
}
.q-app .dss-skip-to-content:focus:focus-visible {
  outline: none;
  box-shadow: var(--dss-focus-shadow-primary);
}
@media (prefers-reduced-motion: no-preference) {
