  box-shadow: none;
}
.q-app .dss-skip-to-content:focus:not([tabindex]):not(button):not(a):not(input):not(select):not(textarea):not([contenteditable]):focus {
  outline: none;
  box-shadow: none;
}

/* High contrast utilities */
@media (prefers-contrast: high) {
  .dss-high-contrast .q-btn {
    border: 2px solid currentColor !important;
  }
