  }
  .dss-high-contrast .q-tab--active {
    text-decoration: underline !important;
    text-underline-offset: 4px !important;
  }
}

/* Reduced motion utilities */
@media (prefers-reduced-motion: reduce) {
  .dss-reduced-motion .q-btn,
  .dss-reduced-motion .q-card,
  .dss-reduced-motion .q-tab,
  .dss-reduced-motion .q-item,
  .dss-reduced-motion .q-table tr {
    transition: none !important;
  }
  .dss-reduced-motion .q-spinner,
  .dss-reduced-motion .q-linear-progress__model {
    animation: none !important;
  }
  .dss-reduced-motion .q-menu,
  .dss-reduced-motion .q-dialog {
    animation: none !important;
    transition: none !important;
  }
}

