/* 4. Importar Quasar variables com nossas customizações */
/* 5. Classes de tema global */
.dss-theme {
  /* Aplicar tokens de marca baseado em data-brand */
}
.dss-theme--hub {
  --quasar-primary: var(--dss-brand-primary);
