   ========================================================================== */
/* Primeiro filho: remove corners da direita (face interna) */
.dss-btn-group > .dss-button:first-child:not(:only-child) {
  border-top-right-radius: 0;
  border-bottom-right-radius: 0;
}

/* Último filho: remove corners da esquerda (face interna) */
.dss-btn-group > .dss-button:last-child:not(:only-child) {
  border-top-left-radius: 0;
  border-bottom-left-radius: 0;
}

/* Filhos intermediários: sem border-radius */
.dss-btn-group > .dss-button:not(:first-child):not(:last-child) {
  border-radius: 0;
}

/* ==========================================================================
