  border-color: var(--dss-hub-600);
  color: var(--dss-hub-600);
}

[data-brand=hub].dss-badge,
.dss-badge--brand-hub.dss-badge {
  /* Variante transparent */
}

[data-brand=hub].dss-badge.dss-badge--transparent,
.dss-badge--brand-hub.dss-badge.dss-badge--transparent {
  background-color: transparent;
  border-color: var(--dss-hub-600);
