.dss-badge--brand-water.dss-badge.dss-badge--outline {
  background-color: transparent;
  border-color: var(--dss-water-500);
  color: var(--dss-water-500);
}

[data-brand=water].dss-badge,
.dss-badge--brand-water.dss-badge {
  /* Variante transparent */
}

[data-brand=water].dss-badge.dss-badge--transparent,
.dss-badge--brand-water.dss-badge.dss-badge--transparent {
  background-color: transparent;
  border-color: var(--dss-water-500);
  color: var(--dss-water-500);
