/* ==========================================================================
   WASTE BRAND (Green)
   ========================================================================== */
[data-brand=waste].dss-badge,
.dss-badge--brand-waste.dss-badge {
  background-color: var(--dss-waste-600);
  color: var(--dss-gray-50);
  /* Variante outline */
}

[data-brand=waste].dss-badge.dss-badge--outline,
.dss-badge--brand-waste.dss-badge.dss-badge--outline {
  background-color: transparent;
