  .dss-checkbox__control {
    /* Bordas mais visiveis em high contrast */
    border-width: var(--dss-border-width-thick);
  }
  /* Focus ring mais forte */
  .dss-checkbox__control--focused {
    outline-width: var(--dss-border-width-thick);
    outline-offset: var(--dss-border-width-thick);
  }
