  --dss-banner-icon-color: var(--dss-text-body);
}

/* ==========================================================================
   INFO — Azul informativo
   Fundo: --dss-feedback-info-surface (rgba info, 10%)
   Borda: --dss-feedback-info (cor info padrão)
   Ícone: --dss-feedback-info (cor info padrão)
