  border-left-color: var(--dss-feedback-info);
  --dss-banner-icon-color: var(--dss-feedback-info-deep);
}

/* ==========================================================================
   SUCCESS — Verde sucesso
   Fundo: --dss-feedback-success-surface (rgba positive, 10%)
   Borda: --dss-feedback-success (cor positive padrão)
   Ícone: --dss-feedback-success-deep (verde mais escuro para contraste)
   ========================================================================== */
.dss-banner--success {
  background-color: var(--dss-feedback-success-surface);
  border-left-color: var(--dss-feedback-success);
  --dss-banner-icon-color: var(--dss-feedback-success-deep);
}

/* ==========================================================================
   WARNING — Amarelo aviso
   Fundo: --dss-feedback-warning-surface (rgba warning, 10%)
   Borda: --dss-feedback-warning (cor warning padrão)
   Ícone: --dss-feedback-warning-deep (tom mais escuro para contraste)
   ========================================================================== */
.dss-banner--warning {
  background-color: var(--dss-feedback-warning-surface);
  border-left-color: var(--dss-feedback-warning);
  --dss-banner-icon-color: var(--dss-feedback-warning-deep);
