   ========================================================================== */
@media (forced-colors: active) {
  .dss-banner {
    border-left-color: ButtonText;
    background-color: Canvas;
    color: CanvasText;
    outline: 1px solid ButtonText;
  }
  .dss-banner__icon {
    forced-color-adjust: auto;
  }
