   EXC-States-01: prefers-contrast: more é o valor válido (NOT "high")
   ========================================================================== */
@media (prefers-contrast: more) {
  .dss-bottom-sheet {
    outline: var(--dss-border-width-md) solid var(--dss-text-body);
    outline-offset: var(--dss-border-width-md);
  }
  .dss-bottom-sheet .dss-bottom-sheet__header {
    border-width: var(--dss-border-width-md);
  }
  .dss-bottom-sheet .dss-bottom-sheet__handle {
    background-color: var(--dss-text-body);
  }
}
/* ==========================================================================
   FORCED COLORS — Windows High Contrast Mode (WCAG 1.4.11)
   SystemColor keywords: ButtonText, ButtonFace, CanvasText, Canvas,
   Highlight, HighlightText, LinkText, VisitedText
   ========================================================================== */
@media (forced-colors: active) {
  .dss-bottom-sheet {
    background-color: Canvas !important;
    color: CanvasText;
    border: var(--dss-border-width-thin) solid ButtonText;
    box-shadow: none !important;
  }
  .dss-bottom-sheet .dss-bottom-sheet__header {
    border-color: ButtonText;
  }
  .dss-bottom-sheet .dss-bottom-sheet__handle {
    background-color: ButtonText;
  }
}
/* ==========================================================================
   REDUCED MOTION — prefers-reduced-motion: reduce
   Transições já gerenciadas pelos tokens via _motion.scss
   ========================================================================== */
@media (prefers-reduced-motion: reduce) {
  .dss-bottom-sheet {
    will-change: auto;
  }
}
/* ==========================================================================
   PRINT
   EXC-04: !important necessário para garantir visibilidade em impressão
