}

.dss-cadris-card__residuos-text {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.dss-cadris-card__residuos-chevron {
  flex-shrink: 0;
  color: var(--dss-text-secondary);
}

.dss-cadris-card__skeleton {
  padding: var(--dss-spacing-4);
  display: flex;
  flex-direction: column;
  gap: var(--dss-spacing-2);
}

.dss-cadris-card__skeleton-row {
  display: flex;
  gap: var(--dss-spacing-4);
  align-items: center;
}

.dss-cadris-card__skeleton-cell {
  height: var(--dss-spacing-4);
  background-color: var(--dss-surface-muted);
  border-radius: var(--dss-radius-sm);
  animation: dss-cadris-shimmer var(--dss-duration-1000) infinite linear;
}

.dss-cadris-card__skeleton-cell--sm {
  flex: 1;
}

.dss-cadris-card__skeleton-cell--md {
  flex: 2;
}

.dss-cadris-card__skeleton-cell--lg {
  flex: 3;
}

@keyframes dss-cadris-shimmer {
  0% {
    opacity: 1;
  }
  50% {
    opacity: 0.4;
  }
  100% {
    opacity: 1;
  }
}
.dss-cadris-card__empty {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  padding: var(--dss-spacing-12) var(--dss-spacing-6);
  text-align: center;
  color: var(--dss-text-secondary);
}

.dss-cadris-card__empty-icon {
  color: var(--dss-text-secondary);
  margin-bottom: var(--dss-spacing-3);
}

.dss-cadris-card__empty-message {
  font-size: var(--dss-font-size-md);
  font-weight: var(--dss-font-weight-medium);
  color: var(--dss-text-primary);
  margin: 0 0 var(--dss-spacing-1);
}

.dss-cadris-card__empty-hint {
  font-size: var(--dss-font-size-sm);
  color: var(--dss-text-secondary);
  margin: 0;
}

.dss-cadris-card__form-pagination {
  display: flex;
  flex-direction: row;
  align-items: center;
  justify-content: flex-end;
  gap: var(--dss-spacing-1);
  padding: 0 var(--dss-spacing-4) var(--dss-spacing-2);
}

.dss-cadris-card__pagination {
  border-top: 1px solid var(--dss-gray-200);
  padding: var(--dss-spacing-2) var(--dss-spacing-3);
  gap: var(--dss-spacing-1);
}

.dss-cadris-card__pagination-label {
  font-size: var(--dss-font-size-sm);
  color: var(--dss-text-secondary);
  white-space: nowrap;
}

.dss-cadris-card__rows-select {
  min-width: 4rem;
}

.dss-cadris-card__pagination-range {
  font-size: var(--dss-font-size-sm);
  color: var(--dss-text-secondary);
  margin: 0 var(--dss-spacing-2);
  white-space: nowrap;
}

.dss-cadris-card__footer {
  display: flex;
  justify-content: center;
  border-top: 1px solid var(--dss-gray-200);
  padding: var(--dss-spacing-3) var(--dss-spacing-4);
}

.dss-cadris-card__fechar-btn {
  min-width: var(--dss-spacing-24);
}

.dss-cadris-card--compact .dss-cadris-card__pesquisa-section {
  padding: var(--dss-spacing-2) var(--dss-spacing-3) 0;
}

.dss-cadris-card--compact .dss-cadris-card__total-label {
  padding: var(--dss-spacing-1) var(--dss-spacing-3);
}

.dss-cadris-card--compact .dss-cadris-card__cell,
.dss-cadris-card--compact .dss-cadris-card__thead th[role=columnheader] {
  padding: var(--dss-spacing-2) var(--dss-spacing-3);
}

.dss-cadris-card--compact .dss-cadris-card__pagination {
  padding: var(--dss-spacing-1) var(--dss-spacing-2);
}

.dss-cadris-card--compact .dss-cadris-card__footer {
  padding: var(--dss-spacing-2) var(--dss-spacing-3);
}

.dss-cadris-card--borderless .dss-cadris-card__pesquisa-section,
.dss-cadris-card--borderless .dss-cadris-card__total-label,
.dss-cadris-card--borderless .dss-cadris-card__pagination,
.dss-cadris-card--borderless .dss-cadris-card__footer {
  border-color: transparent;
}

.dss-cadris-card--disabled {
  opacity: var(--dss-opacity-disabled);
  pointer-events: none;
  user-select: none;
}

.dss-cadris-card--loading {
  pointer-events: none;
}

@media (prefers-color-scheme: dark) {
  .dss-cadris-card__thead th[role=columnheader] {
    border-bottom-color: var(--dss-gray-600);
  }
  .dss-cadris-card__tbody .dss-cadris-card__row {
    border-bottom-color: var(--dss-gray-700);
  }
  .dss-cadris-card__toolbar, .dss-cadris-card__filters, .dss-cadris-card__actions, .dss-cadris-card__pagination {
    border-color: var(--dss-gray-700);
  }
}
@media (prefers-reduced-motion: reduce) {
  .dss-cadris-card__skeleton-cell {
    animation: none;
  }
}
@media (forced-colors: active) {
  .dss-cadris-card__table {
    border: 1px solid ButtonText;
  }
  .dss-cadris-card__thead th[role=columnheader] {
    background-color: ButtonFace;
    color: ButtonText;
    border-bottom: 2px solid ButtonText;
  }
  .dss-cadris-card__tbody .dss-cadris-card__row {
    border-bottom: 1px solid ButtonText;
  }
  .dss-cadris-card__tbody .dss-cadris-card__row:hover {
    outline: 2px solid Highlight;
    outline-offset: -2px;
  }
  .dss-cadris-card__status {
    forced-color-adjust: none;
  }
}
@media print {
  .dss-cadris-card__actions, .dss-cadris-card__pagination {
    display: none;
  }
  .dss-cadris-card__skeleton {
    display: none;
  }
  .dss-cadris-card__table {
    page-break-inside: avoid;
  }
}
[data-brand=hub] .dss-cadris-card__thead th[role=columnheader] {
  background-color: var(--dss-surface-muted);
  border-bottom-color: var(--dss-hub-primary, var(--dss-gray-300));
}

[data-brand=hub] .dss-cadris-card__row:hover {
  background-color: var(--dss-surface-hover);
}

[data-brand=water] .dss-cadris-card__thead th[role=columnheader] {
  background-color: var(--dss-surface-muted);
  border-bottom-color: var(--dss-water-primary, var(--dss-gray-300));
}

[data-brand=water] .dss-cadris-card__row:hover {
  background-color: var(--dss-surface-hover);
}

[data-brand=waste] .dss-cadris-card__thead th[role=columnheader] {
  background-color: var(--dss-surface-muted);
  border-bottom-color: var(--dss-waste-primary, var(--dss-gray-300));
}

[data-brand=waste] .dss-cadris-card__row:hover {
  background-color: var(--dss-surface-hover);
}
